#!/usr/bin/env node
"use strict";
// Generates rules.js from rules.json (the single source of truth).
// Usage: node scripts/build-rules.js
const fs = require("node:fs");
const path = require("node:path");

const root = path.join(__dirname, "..");

function generate(jsonText) {
  const data = JSON.parse(jsonText);
  return (
    "// Generated by scripts/build-rules.js from rules.json. Do not edit by hand.\n" +
    "(function (root) {\n" +
    "  var rules = " + JSON.stringify(data, null, 2).replace(/\n/g, "\n  ") + ";\n" +
    "  if (typeof module !== \"undefined\" && module.exports) { module.exports = rules; }\n" +
    "  else { root.DYD_RULES = rules; }\n" +
    "})(typeof window !== \"undefined\" ? window : this);\n"
  );
}

module.exports = { generate };

if (require.main === module) {
  const src = fs.readFileSync(path.join(root, "rules.json"), "utf8");
  fs.writeFileSync(path.join(root, "rules.js"), generate(src));
  console.log("rules.js written from rules.json");
}
